33		// already produced output survives.
34		failInput := input + "\n" + `{"type":"watermark","time":1999,"partition":1}` + "\n"
35		got, _, err := runPartitioned(t, failInput, 1000, 2)
36		if err == nil {
37			t.Fatal("expected resume at 1999 to fail")
38		}
39		inputErr, ok := err.(*InputError)
