mkdir -p /tmp/wmperf && cat > /tmp/wmperf/main.go <<'EOF'
package main

import (
	"fmt"
	"io"
	"strings"
	"time"

	"github.com/asdhoaiqqq/edgefleet-validator/edgefleet"
)

func run(p int) time.Duration {
	var b strings.Builder
	// one pending event per partition, then watermarks in ascending order,
	// partition p-1 (the laggard) reporting last
	for i := 0; i < p; i++ {
		fmt.Fprintf(&b, `{"type":"event","key":"k","time":100,"value":1,"partition":%d}`+"\n", i)
	}
	for i := 0; i < p; i++ {
		fmt.Fprintf(&b, `{"type":"watermark","time":500,"partition":%d}`+"\n", i)
	}
	input := b.String()
	start := time.Now()
	if err := edgefleet.RunAggregatePartitioned(strings.NewReader(input), 1000, int64(p), io.Discard, io.Discard); err != nil {
		panic(err)
	}
	return time.Since(start)
}

func main() {
	for _, p := range []int{2000, 4000, 8000, 16000} {
		fmt.Printf("partitions=%6d  %v\n", p, run(p))
	}
}
EOF
