cat > /tmp/wmperf/equiv.go <<'EOF'
package main

import (
	"bytes"
	"fmt"
	"strings"

	"github.com/asdhoaiqqq/edgefleet-validator/edgefleet"
)

func run(input string, window, parts int64) (string, string, error) {
	var out, late bytes.Buffer
	err := edgefleet.RunAggregatePartitionedSliding(strings.NewReader(input), window, window, parts, &out, &late)
	return out.String(), late.String(), err
}

func main() {
	const P = 6
	// same pending events in every scenario
	var ev strings.Builder
	for i := 0; i < P; i++ {
		fmt.Fprintf(&ev, `{"type":"event","key":"k%d","time":%d,"value":%d,"partition":%d}`+"\n", i%3, 100+100*i, i+1, i)
	}
	wm := func(p, t int) string { return fmt.Sprintf(`{"type":"watermark","time":%d,"partition":%d}`, t, p) }

	// scenario A: ascending first reports, all at time 1000 except p5 at 2500
	var a strings.Builder
	a.WriteString(ev.String())
	for i := 0; i < P-1; i++ {
		a.WriteString(wm(i, 1000) + "\n")
	}
	a.WriteString(wm(P-1, 2500) + "\n")

	// scenario B: same records, descending report order
	var b strings.Builder
	b.WriteString(ev.String())
	b.WriteString(wm(P-1, 2500) + "\n")
	for i := P - 2; i >= 0; i-- {
		b.WriteString(wm(i, 1000) + "\n")
	}

	// scenario C: interleaved with repeated watermarks and repeated idles
	var c strings.Builder
	c.WriteString(ev.String())
	c.WriteString(wm(2, 1000) + "\n")
	c.WriteString(wm(2, 1000) + "\n") // repeat must not count twice
	c.WriteString(`{"type":"idle","partition":4}` + "\n")
	c.WriteString(`{"type":"idle","partition":4}` + "\n") // repeat no-op
	c.WriteString(wm(0, 1000)+"\n"+wm(1, 1000)+"\n"+wm(3, 1000)+"\n")
	c.WriteString(wm(4, 1000)+"\n") // resume p4
	c.WriteString(wm(5, 2500) + "\n")

	oa, la, erra := run(a.String(), 1000, P)
	ob, lb, errb := run(b.String(), 1000, P)
	oc, lc, errc := run(c.String(), 1000, P)
	fmt.Printf("A err=%v\nB err=%v\nC err=%v\n", erra, errb, errc)
	fmt.Printf("A==B output: %v, late: %v\n", oa == ob, la == lb)
	fmt.Printf("A==C output: %v, late: %v\n", oa == oc, la == lc)
	fmt.Printf("output:\n%s", oa)

	// all idle, never established: no output, events retained silently
	var d strings.Builder
	d.WriteString(ev.String())
	for i := 0; i < P; i++ {
		fmt.Fprintf(&d, `{"type":"idle","partition":%d}`+"\n", i)
	}
	od, ld, errd := run(d.String(), 1000, P)
	fmt.Printf("all-idle: err=%v out=%q late=%q\n", errd, od, ld)

	// backward watermark must not count as a report: p1 regresses -> fatal,
	// and no window may have closed from counting it
	bad := ev.String() + wm(0, 1000) + "\n" + wm(1, 3000) + "\n" + wm(1, 2000) + "\n"
	oe, le, erre := run(bad, 1000, P)
	fmt.Printf("backward: err=%v out=%q late=%q\n", erre, oe, le)
}
EOF
